function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function ext(url,label,cls='text-link'){const safe=/^https:\/\//.test(url)?url:'https://koreans.kz/';return `<a href="${esc(safe)}" target="_blank" rel="noopener noreferrer" class="${cls}">${label} ↗</a>`}
function heading(eyebrow,title,subtitle,tag=''){return `<div class="page-intro"><div><div class="eyebrow"><span class="dot"></span>${eyebrow}</div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${tag?`<span class="subtle-tag">${tag}</span>`:''}</div>`}
function section(title,link='',label='Смотреть всё',eyebrow=''){return `<div class="section-head"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h2>${title}</h2></div>${link?`<a class="text-link" href="#${link}">${label} →</a>`:''}</div>`}
function back(route='home',label='Назад'){return `<a class="back" href="#${route}">${icon('back')}${label}</a>`}
function bookmark(id){return `<button class="bookmark ${saved.has(id)?'saved':''}" data-save="${esc(id)}" aria-label="${saved.has(id)?'Убрать из избранного':'Добавить в избранное'}" aria-pressed="${saved.has(id)}">${icon('bookmark')}</button>`}
function newsCard(n){return `<a class="news-card" href="#article/${encodeURIComponent(n.id)}"><div class="news-art type${n.art||0}"><span class="art-category">${esc(n.category)}</span></div><div class="news-body"><div class="meta">${esc(n.source)}<i></i>${formatDate(n.date)}</div><h3>${esc(n.title)}</h3><div class="read">Читать материал <span>↗</span></div></div></a>`}
function formatDate(s){const d=new Date(s+'T12:00:00');return isNaN(d)?esc(s):d.toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}
function memberPanel(){return `<div class="member-panel"><div class="eyebrow">МОЙ АКК</div><div class="card-emblem">${icon('user')}</div><h3>Ваше место<br>в сообществе</h3><p>Расскажите о себе и присоединяйтесь к жизни Ассоциации.</p><a href="#profile" class="primary">${draft.first_name?'Продолжить анкету':'Стать участником'} ${icon('arrow')}</a><small>Анкета займёт несколько минут</small></div>`}
function home(){return heading('АССОЦИАЦИЯ КАЗАХСТАНСКИХ КОРЕЙЦЕВ','Своё сообщество. Рядом.','Люди, культура и возможности, которые нас объединяют.','КАЗАХСТАН')+`<div class="home-layout"><div class="home-main"><section class="hero photo-hero"><img class="hero-landscape" src="./assets/kpark/01-hero.webp" alt="K-PARK — рендер проекта"><div class="hero-copy"><div class="eyebrow">НАСЛЕДИЕ, КОТОРОЕ ОБЪЕДИНЯЕТ</div><h2>Помним корни.<br>Создаём будущее.</h2><p>Откройте K-PARK — новое пространство культуры и встреч в Алатау.</p><a class="primary" href="#kpark">Знакомство с K-PARK ${icon('arrow')}</a></div><span class="hero-number">K-PARK / 2027</span><div class="hero-art" aria-hidden="true"><i></i><i></i><i></i></div></section>${section('Жизнь Ассоциации','community','Все направления')}<div class="module-grid">${departments.map(d=>`<a href="#${d.id}" class="module"><span class="module-icon" style="background:${d.color}"><img src="./assets/${d.image}" alt=""></span><strong>${d.name}</strong><small>${d.label}</small></a>`).join('')}</div>${section('В фокусе сообщества','news','Все материалы','НОВОСТИ И ИСТОРИИ')}<div class="news-grid">${news.slice(0,2).map(newsCard).join('')}</div><div class="muted-note">Публикации редакции «Корё ильбо» · даты указаны по первоисточнику.</div>${section('Встречаемся вместе','events','Афиша')}<div class="event-list">${events.slice(0,1).map(eventCard).join('')}</div></div><aside class="home-rail">${memberPanel()}<div class="rail-card"><h3>Ближе, чем кажется</h3><p>Найдите региональное сообщество и оставайтесь на связи.</p><a class="rail-row" href="#branches">${icon('pin')}Филиалы по Казахстану<span>→</span></a><a class="rail-row" href="#structure">${icon('people')}Структура АКК<span>→</span></a><a class="rail-row" href="#opportunities">${icon('briefcase')}Возможности<span>→</span></a></div><div class="rail-card"><div class="eyebrow">НАША ИСТОРИЯ ПРОДОЛЖАЕТСЯ</div><h3 style="font-size:32px;font-weight:500;margin:15px 0 5px">90 лет</h3><p>История поколений.<br>Будущее, которое мы создаём вместе.</p><a class="text-link" href="#anniversary">Программа 90-летия →</a></div></aside></div>`}
function community(){return heading('ЛЮДИ И НАПРАВЛЕНИЯ','Вместе — больше.','Выберите то, что близко вам: культуру, развитие, общение или общее дело.')+`<div class="grid">${departments.map(d=>`<a class="community-card" href="#${d.id}"><div class="logo-box" style="background:${d.color}"><img src="./assets/${d.image}" alt="${d.name}"></div><h3>${d.name}</h3><p>${d.description}</p><div class="card-foot">${d.label}<span>→</span></div></a>`).join('')}<a class="community-card" href="#branches"><div class="logo-box">${icon('pin')}</div><h3>Филиалы АКК</h3><p>Ваш регион, знакомые лица и общие инициативы.</p><div class="card-foot">Найти своё сообщество<span>→</span></div></a><a class="community-card" href="#structure"><div class="logo-box">${icon('people')}</div><h3>Структура АКК</h3><p>Совет старейшин, Попечительский совет и региональные филиалы.</p><div class="card-foot">Как устроена Ассоциация<span>→</span></div></a></div><div class="wide-banner"><div><div class="eyebrow">МАЛЕНЬКИЙ ШАГ К БОЛЬШОМУ СООБЩЕСТВУ</div><h3>У каждого есть чем поделиться.</h3><p>Опыт, идеи, творчество или время — найдите своё направление участия.</p></div><a class="primary" href="#opportunities">Найти возможность ${icon('arrow')}</a></div>`}
function eventCard(e){const d=new Date(e.date+'T12:00:00');return `<article class="event-card"><div class="date-box"><b>${d.getDate()}</b><small>${d.toLocaleDateString('ru-RU',{month:'short'}).replace('.','').toUpperCase()}</small></div><div class="event-copy"><div class="meta">${esc(e.city)}<i></i>${esc(e.category)}${e.planned?'<i></i>План':''}</div><a href="#event/${e.id}"><h3>${esc(e.title)}</h3><p>${e.planned?'В программе 2027 года · подробности уточняются':'Подробнее о мероприятии'}</p></a></div>${bookmark('event:'+e.id)}</article>`}
function eventsPage(){const list=events.filter(e=>(eventFilter==='Все'||e.category===eventFilter)&&(region==='Весь Казахстан'||e.city===region||e.id==='kpark-opening'));return heading('КАЛЕНДАРЬ СООБЩЕСТВА','Повод встретиться.','Культурные события, встречи и общие проекты.')+`<div class="chips" role="group" aria-label="Фильтр афиши">${['Все','АКК','Театр','МДК'].map(x=>`<button class="chip ${eventFilter===x?'active':''}" data-event-filter="${x}" aria-pressed="${eventFilter===x}">${x}</button>`).join('')}</div>${eventFilter==='Театр'?theatreTickets():list.length?`<div class="event-list">${list.map(eventCard).join('')}</div><p class="muted-note">В календаре указаны плановые даты программы 90-летия. Время, площадки и условия участия публикуются после подтверждения организаторами.</p>`:empty('Новые встречи впереди','Для выбранного региона и направления пока нет опубликованных мероприятий.','Вся афиша','events')}<div class="wide-banner"><div><div class="eyebrow">КОРЕЙСКИЙ ТЕАТР</div><h3>Вечер, который запомнится.</h3><p>Узнайте текущую афишу и выберите спектакль на официальных билетных площадках.</p></div><a class="secondary" href="#theatre">Театр и билеты →</a></div>`}
function eventDetail(id){const e=events.find(x=>x.id===id);if(!e)return notFound();return back('events','Афиша')+heading('ПРОГРАММА 90-ЛЕТИЯ',esc(e.title),`${formatDate(e.date)} 2027 · ${esc(e.city)}`)+`<div class="info-card"><div class="eyebrow">ПЛАНОВОЕ МЕРОПРИЯТИЕ</div><p>${esc(e.description)}</p><p>Регистрация откроется после публикации окончательной программы. Сохраните событие, чтобы быстро вернуться к нему из профиля.</p><div class="form-actions">${bookmark('event:'+e.id)}<button class="secondary" data-calendar="${e.id}">${icon('calendar')}В календарь</button>${e.url?ext(e.url,'Страница проекта','primary'):''}</div></div>`}
function empty(title,text,label,route){return `<div class="empty">${icon('calendar')}<h3>${title}</h3><p>${text}</p>${route?`<a class="secondary" href="#${route}">${label} →</a>`:''}</div>`}
function kpark(){return heading('КУЛЬТУРНО-ДЕЛОВОЙ ЦЕНТР','K-PARK','Память, культура и пространство для будущих поколений.','АЛАТАУ · КАЗАХСТАН')+`<section class="feature-banner kpark-feature render-feature"><img class="park-hero-image" src="./assets/kpark/01-hero.webp" alt="K-PARK — рендер проекта"><img class="logo-k" src="./assets/9cbf9eee8e3c0066.png" alt="K-PARK"><div class="eyebrow">ИСТОРИЯ ПРОДОЛЖАЕТСЯ ЗДЕСЬ</div><h2>Место, где<br>встречаются<br>поколения.</h2><p>Символ благодарности казахскому народу. Пространство культуры, открытий и встреч в новом городе Алатау.</p><div class="actions"><a class="primary" href="#kpark-about">Открыть проект ${icon('arrow')}</a><a class="secondary outline" href="#kpark-support">Поддержать ${icon('heart')}</a></div></section><div class="stat-row"><div class="stat"><b>2027</b><small>планируемое открытие</small></div><div class="stat"><b>10 га</b><small>площадь территории</small></div><div class="stat"><b>90 лет</b><small>истории сообщества</small></div></div>${parkGallery()}${section('Больше, чем парк','','','ПРОСТРАНСТВО ВОЗМОЖНОСТЕЙ')}<div class="info-grid">${[['building','Культурный центр','Выставочные пространства, библиотека, конференц-зал и место для встреч сообщества.'],['book','История и наследие','Сохранение памяти корё-сарам и диалог между поколениями.'],['people','Амфитеатр','Сцена для культурных событий, выступлений и больших встреч.'],['leaf','Парк для всех','Зелёные маршруты и общественные пространства для ежедневной жизни.']].map(([i,t,p])=>`<div class="info-card">${icon(i)}<h3>${t}</h3><p>${p}</p></div>`).join('')}</div>${parkZones()}${section('От идеи к общему будущему','','','ПУТЬ ПРОЕКТА')}<div class="info-card timeline"><div class="timeline-item"><small>12 СЕНТЯБРЯ 2025</small><h3>Заложен первый камень</h3><p>В Алатау состоялась торжественная церемония начала проекта.</p></div><div class="timeline-item"><small>СЕЙЧАС</small><h3>Создаём пространство будущего</h3><p>Официальные сообщения о ходе проекта доступны на странице АКК.</p></div><div class="timeline-item"><small>10 СЕНТЯБРЯ 2027 · ПЛАН</small><h3>Открытие K-PARK</h3><p>Ключевое событие программы 90-летия корейцев Казахстана.</p></div></div><div class="wide-banner"><div><h3>Большое будущее начинается с участия.</h3><p>Узнайте, как поддержать проект, стать партнёром или присоединиться к волонтёрской команде.</p></div><a class="primary" href="#kpark-support">Принять участие ${icon('arrow')}</a></div>`}
function kparkAbout(){return back('kpark','K-PARK')+heading('ПАМЯТЬ И БУДУЩЕЕ','Пространство благодарности.','Культурно-деловой центр в Алатау · территория 10 га')+`<div class="article"><p>K-PARK — проект Ассоциации, объединяющий культуру, историю и общественную жизнь. Его идея — сохранить наследие корё-сарам и выразить благодарность казахскому народу.</p><p>Площадь K-PARK — <strong>10 га</strong>. Проект расположен в Golden District города Алатау, в 11 км от Алматы.</p><p>Проект включает 14 функциональных зон: от входной площади и визит-центра до корейского сада, пруда и площадки для аэротакси. Полный перечень представлен на главной странице K-PARK.</p><p>Первый камень заложен 12 сентября 2025 года. Открытие включено в программу 90-летия корейцев Казахстана на 2027 год.</p><div class="notice">Состав объектов и сроки уточняются по мере реализации проекта. Данные о проценте готовности и онлайн-трансляция будут доступны после официальной публикации.</div><div class="form-actions">${ext('https://koreans.kz/kpark','Официальная страница','primary')}${ext('https://alatau.city/ru/news/fotoreportazh-v-alatau-city-zalozhili-pervyy-kamen-k-park','Фоторепортаж','secondary')}</div></div>`}
function support(){return back('kpark','K-PARK')+heading('ПРИСОЕДИНИТЬСЯ К ПРОЕКТУ','Будущее создаём вместе.','Выберите удобный способ участия.')+`<div class="info-grid"><div class="info-card">${icon('heart')}<h3>Поддержать финансово</h3><p>Проверенные реквизиты и условия пожертвования запрашивайте у Ассоциации. Платёж выполняется только по официальным реквизитам.</p>${ext('https://koreans.kz/kpark','Страница проекта','primary')}</div><div class="info-card">${icon('briefcase')}<h3>Стать партнёром</h3><p>Обсудите с командой АКК возможности сотрудничества и поддержки проекта.</p><a class="secondary" href="mailto:oyulakk@gmail.com?subject=Партнёрство%20с%20K-PARK">Написать в АКК →</a></div><div class="info-card">${icon('people')}<h3>Помочь как волонтёр</h3><p>Укажите в анкете интерес к K-PARK и волонтёрству на мероприятиях 90-летия.</p><a class="secondary" href="#profile">Заполнить анкету →</a></div><div class="info-card">${icon('globe')}<h3>Рассказать о проекте</h3><p>Поделитесь официальной страницей с друзьями и коллегами.</p><button class="secondary" data-share="kpark">Поделиться →</button></div></div>`}
function branches(){return back('community','Сообщество')+heading('РЕГИОНАЛЬНЫЕ СООБЩЕСТВА','Найдите своих.','Региональные филиалы — прямой путь к жизни Ассоциации в вашем городе.')+`<label class="field">Город<input id="branch-search" class="search-input" type="search" placeholder="Начните вводить название города" autocomplete="off"></label><div class="branch-grid" id="branch-list" style="margin-top:22px">${branchCards('')}</div><p class="muted-note">Справочная информация из исходной версии. Перед визитом уточните адрес и контакты на официальной странице филиалов.</p>`}
function branchCards(q){return regions.slice(1).filter(x=>x.toLowerCase().includes(q.toLowerCase())).map(city=>`<a href="#branch/${encodeURIComponent(city)}" class="branch"><div class="eyebrow"><span class="branch-city"></span>ФИЛИАЛ АКК</div><b>${city}</b><p>${esc(addresses[city]||'Контакты на официальной странице')}</p></a>`).join('')||'<p class="muted-note">Город не найден. Попробуйте изменить запрос.</p>'}
function branchDetail(city){if(!regions.includes(city))return notFound();return back('branches','Все филиалы')+heading('РЕГИОНАЛЬНОЕ СООБЩЕСТВО',esc(city),'Филиал Ассоциации казахстанских корейцев')+`<div class="info-card">${icon('pin')}<h3>${esc(addresses[city]||city)}</h3><p>Руководство и контакты филиалов актуализируются Ассоциацией. Используйте официальный справочник для прямой связи.</p>${ext('https://koreans.kz/branches','Контакты филиалов','primary')}</div>`}
function structure(){return back('community','Сообщество')+heading('ОРГАНИЗАЦИЯ','Структура Ассоциации','Состав органов АКК по предоставленному документу.')+`<div class="directory-summary">${councils.map(c=>`<a class="chip" href="#structure" data-council="${councils.indexOf(c)}"><span>${c.title}</span> · ${c.people.length}</a>`).join('')}</div><div class="notice">ФИО и должности приведены на языке исходного документа. <a href="https://www.koreans.kz/ru" target="_blank" rel="noopener noreferrer">Фотографии: koreans.kz ↗</a></div>${councils.map((c,i)=>`<section class="council-section" id="council-${i}"><div class="section-heading"><h2>${c.title}</h2><span>${c.people.length}</span></div><div class="member-grid">${c.people.map((p,j)=>`<article class="member-card">${portraits[p.name]?`<img class="member-portrait" src="${portraits[p.name].file}" alt="${esc(p.name)}" loading="lazy">`:`<span class="member-initials" aria-hidden="true">${esc(p.name.split(/\s+/).slice(0,2).map(x=>x[0]).join(''))}</span>`}<div><h3>${esc(p.needsReview?'Ким … Александровна':p.name)}</h3>${p.needsReview?'<small class="review-note">Имя в документе указано неполностью — требуется уточнение.</small>':''}<p lang="ru">${esc(p.role).replace(/\n/g,'<br>')}</p></div></article>`).join('')}</div></section>`).join('')}<div class="form-actions"><a class="secondary" href="#branches">Региональные филиалы →</a><a class="secondary" href="#mdk">Молодёжное движение →</a></div>`}
function parkZones(){return `<section class="park-zones"><div class="section-heading"><div><div class="eyebrow">K-PARK · 10 га</div><h2>14 функциональных зон</h2></div></div><p class="muted-note">Зоны проекта по предоставленному перечню.</p><div class="zones-grid">${zones.map(z=>`<article class="zone-card">${zoneImages[z.id]?`<img src="./assets/kpark/${zoneImages[z.id]}.webp" alt="${esc(z.ru)} — рендер" loading="lazy">`:icon('leaf')}<b>${String(z.id).padStart(2,'0')}</b><div><h3>${z.ru}</h3><small lang="kk" data-no-translate>${z.kk}</small></div></article>`).join('')}</div></section>`}

function theatreTickets(){return `<div class="info-card">${icon('ticket')}<h3>Выберите свой спектакль</h3><p>Актуальное расписание, наличие мест и стоимость билетов уточняйте на официальном сайте театра и Ticketon.</p><div class="form-actions">${ext('https://ticketon.kz/','Перейти на Ticketon','primary')}${ext('https://koreantheatre.kz/','Сайт театра','secondary')}</div></div>`}
function department(id){let d=departments.find(x=>x.id===id);if(!d)return notFound();let content='';if(id==='mdk')content=`<section class="feature-banner"><div class="eyebrow">ОДНА МЕЧТА · ОДНА КОМАНДА</div><h2>Твоя энергия.<br>Общее движение.</h2><p>Знакомьтесь, учитесь и создавайте проекты в команде Молодёжного движения корейцев Казахстана.</p><div class="actions"><a href="#opportunities" class="primary">Найти своё дело ${icon('arrow')}</a><a href="#profile" class="secondary outline">Присоединиться →</a></div></section><div class="info-grid">${[['people','Региональные команды','Найдите команду в своём городе и включайтесь в общие проекты.','branches'],['briefcase','Возможности','Волонтёрство, творчество, медиа и образование.','opportunities']].map(([i,t,p,r])=>`<a class="info-card" href="#${r}">${icon(i)}<h3>${t}</h3><p>${p}</p><span class="text-link">Подробнее →</span></a>`).join('')}</div><div class="notice">Ваши подтверждённые часы, участие и сертификаты доступны через действующий личный кабинет после авторизации.</div><a class="secondary" href="./previous/index.html#mdk">Открыть действующий кабинет →</a>`;if(id==='theatre')content=`<figure class="photo-story theatre-photo"><img src="./assets/theatre.jpg" alt="Здание Корейского театра в Алматы"><figcaption>Корейский театр, Алматы · фото Tengrinews</figcaption></figure><div class="info-card"><h3>Театр с историей</h3><p>Основан в 1932 году во Владивостоке. С 1968 года работает в Алматы. В репертуаре — корейская, казахская и мировая драматургия; театр объединяет драматическую труппу, танцевальный коллектив и фольклорное направление.</p></div>`+theatreTickets()+`<div class="info-grid"><div class="info-card"><h3>Культура, которая живёт на сцене</h3><p>Спектакли, артисты и история Корейского театра — на его официальном сайте.</p>${ext('https://koreantheatre.kz/','О театре')}</div><a class="info-card" href="#contacts"><h3>Остались вопросы?</h3><p>Контакты Ассоциации и полезные ссылки.</p><span class="text-link">Связаться →</span></a></div>`;if(id==='gazeta')content=`<div class="feature-banner" style="background:#465e51"><div class="eyebrow">ГОЛОС СООБЩЕСТВА</div><h2>Истории, которые<br>остаются с нами.</h2><p>Новости, культура и наследие на страницах «Корё ильбо».</p><div class="actions"><a class="primary" href="#news">Читать материалы ${icon('arrow')}</a>${ext('https://koreilbo.com/archive/','Архив газеты','secondary outline')}</div></div><div class="gazeta-intro"><img src="./assets/newspaper.jpg" alt="Архивная обложка Корё ильбо от 25 августа 2023 года"><div><div class="eyebrow">ГАЗЕТА С 1923 ГОДА</div><h3>Больше века сохраняем голоса поколений.</h3><p>«Корё ильбо» выходит на русском и корейском языках и рассказывает о жизни сообщества, культуре и истории. На фото — архивный выпуск от 25 августа 2023 года.</p><a href="https://koreilbo.com/company/arkhiv-gazety/" target="_blank" rel="noopener" class="text-link">Открыть архив редакции ↗</a></div></div>${section('Материалы редакции','news','Все материалы')}<div class="news-grid">${news.map(newsCard).join('')}</div>`;if(id==='business')content=`<div class="feature-banner" style="background:#5f5545"><div class="eyebrow">ДЕЛОВОЕ СООБЩЕСТВО</div><h2>Связи, которые<br>открывают возможности.</h2><p>Обмен опытом, партнёрства и совместные инициативы предпринимателей.</p><div class="actions">${ext('https://koreans.kz/business-club','О Деловом клубе','primary')}<a href="#profile" class="secondary outline">Рассказать о себе →</a></div></div><div class="info-grid"><div class="info-card">${icon('briefcase')}<h3>Вакансии и сотрудничество</h3><p>Предложения участников публикуются после подтверждения организаторами.</p><a class="text-link" href="#opportunities">Возможности →</a></div><div class="info-card">${icon('heart')}<h3>Привилегии участников</h3><p>Условия партнёрской программы доступны по мере согласования с компаниями.</p><a class="text-link" href="#benefits">Подробнее →</a></div></div>`;return back('community','Сообщество')+heading(d.label.toUpperCase(),d.name,d.description)+content}
