let oppCategory='Все',oppFormat='Все',oppQuery='',oppTab='catalog',oppSkills=storage.get('oppSkills',[]),oppDrafts=storage.get('oppDrafts',{});
function oppScore(o){return o.skills.filter(s=>oppSkills.includes(s)).length}
function opportunities(){let list=opportunitiesData.filter(o=>(oppCategory==='Все'||o.category===oppCategory)&&(oppFormat==='Все'||o.format===oppFormat)&&(o.title+' '+o.category+' '+o.org+' '+o.skills.join(' ')).toLowerCase().includes(oppQuery.toLowerCase()));if(oppTab==='recommended')list.sort((a,b)=>oppScore(b)-oppScore(a));return heading('ВОЗМОЖНОСТИ АКК','Найдите своё дело.','Ваш опыт и интересы могут стать началом общего проекта.')+`<section class="opportunity-hero"><div><div class="eyebrow">ОТ ИНТЕРЕСА — К УЧАСТИЮ</div><h2>Здесь есть место<br>вашим сильным сторонам.</h2><p>Выберите интересы. Найдите направление. Подготовьте отклик.</p><button class="primary" id="opp-quiz">Подобрать направление ${icon('arrow')}</button></div><div class="opp-orbit" aria-hidden="true">${icon('people')}<span>КУЛЬТУРА</span><span>РАЗВИТИЕ</span><span>ОБЩЕЕ ДЕЛО</span></div></section><div class="opp-tabs" role="group" aria-label="Разделы возможностей">${[['catalog','Каталог'],['recommended','Подобрано для вас'],['mine','Мои отклики · '+Object.keys(oppDrafts).length]].map(([id,t])=>`<button class="${oppTab===id?'active':''}" data-opp-tab="${id}" aria-pressed="${oppTab===id}">${t}</button>`).join('')}</div>${oppTab==='mine'?oppMine():`<div class="opp-controls"><label class="field">Поиск<input id="opp-search" type="search" placeholder="Навык, направление или роль" value="${esc(oppQuery)}"></label><label class="field">Формат<select id="opp-format">${['Все','Онлайн','Офлайн','Гибрид'].map(x=>`<option ${oppFormat===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="chips">${['Все','Волонтёрство','Образование','Медиа','Культура','Бизнес','Сообщество'].map(x=>`<button class="chip ${oppCategory===x?'active':''}" data-opp-category="${x}">${x}</button>`).join('')}</div>${oppTab==='recommended'?`<div class="notice">${oppSkills.length?'Подбор по вашим интересам: '+oppSkills.map(esc).join(', ')+'.':'Укажите интересы, чтобы упорядочить направления по совпадению навыков.'} <button class="text-link" id="opp-quiz">Изменить интересы →</button></div>`:''}<div class="opp-results-label" id="opp-count">Найдено: ${list.length} · направления участия</div><div class="opp-grid" id="opp-list">${list.map(oppCard).join('')||'<p>Ничего не найдено. Измените фильтры.</p>'}</div><div class="notice">Здесь представлены направления участия и официальные ресурсы. Примерные роли и задачи предложены для знакомства; начало работы, условия и сроки подтверждаются организатором.</div>`}`}
function oppCard(o){return `<article class="opp-card"><div class="opp-card-top"><div class="opp-icon">${icon(o.icon)}</div>${bookmark('opportunity:'+o.id)}</div><div class="eyebrow">${o.category} · ${o.format}</div><a href="#opportunity/${o.id}"><h3>${o.title}</h3></a><p>${o.lead}</p><div class="skill-tags">${o.skills.map(s=>`<span class="${oppSkills.includes(s)?'match':''}">${s}</span>`).join('')}</div><div class="opp-card-bottom"><span>${oppScore(o)?'Совпало интересов: '+oppScore(o):o.status}</span><a href="#opportunity/${o.id}" aria-label="Подробнее: ${o.title}">Подробнее →</a></div></article>`}
function oppMine(){const entries=Object.entries(oppDrafts);return entries.length?`<p class="muted-note">Черновики сохраняются на этом устройстве. Организатор не получает их автоматически.</p><div class="opp-grid">${entries.map(([id,d])=>{const o=opportunitiesData.find(x=>x.id===id);if(!o)return '';return `<article class="opp-card"><div class="eyebrow">ЧЕРНОВИК ОТКЛИКА</div><h3>${o.title}</h3><p>${esc(d.message)}</p><div class="skill-tags"><span>${esc(d.availability||'Время не указано')}</span></div><div class="form-actions"><button class="secondary" data-opp-edit="${id}">Продолжить</button><button class="text-link" data-opp-remove="${id}">Удалить</button></div></article>`}).join('')}</div>`:empty('Первый шаг ещё впереди','Откройте интересное направление и подготовьте отклик. Здесь он сохранится как черновик.','Перейти к каталогу','opportunities')}
function opportunityDetail(id){const o=opportunitiesData.find(x=>x.id===id);if(!o)return notFound();return back('opportunities','Все возможности')+heading(o.category.toUpperCase(),o.title,o.org)+`<div class="opportunity-detail"><div><div class="opp-detail-intro"><div class="skill-tags"><span>${o.format}</span><span>${o.status}</span></div><p>${o.lead}</p></div><div class="info-card"><h3>Чем можно заняться</h3><ul class="task-list">${o.tasks.map(t=>`<li>${icon('check')}<span>${t}</span></li>`).join('')}</ul><h3>Результат участия</h3><p>${o.result}</p><h3>Какие навыки пригодятся</h3><div class="skill-tags">${o.skills.map(s=>`<span>${s}</span>`).join('')}</div></div><div class="notice">Роли и задачи — предложение для обсуждения с организатором. Требования, доступность и даты не подменяются предположениями.</div></div><aside><div class="rail-card"><div class="eyebrow">ВАШ СЛЕДУЮЩИЙ ШАГ</div><h3>Начните с короткого отклика.</h3><p>Расскажите об опыте, мотивации и удобном формате участия.</p><button class="primary" data-opp-edit="${id}">Подготовить отклик →</button><div class="form-actions">${bookmark('opportunity:'+id)}</div></div><div class="rail-card"><h3>Проверить первоисточник</h3><p>О направлении и контактах организатора.</p>${ext(o.source,'Официальная страница')}</div></aside></div>`}
function oppQuiz(){const skills=[...new Set(opportunitiesData.flatMap(o=>o.skills))];openModal('Что вам интересно?',`<p>Выберите до пяти интересов. Подбор сравнивает их с навыками направлений.</p><div class="quiz-skills">${skills.map(s=>`<label><input type="checkbox" name="opp-skill" value="${s}" ${oppSkills.includes(s)?'checked':''}><span>${s}</span></label>`).join('')}</div><button class="primary" id="opp-quiz-save" style="margin-top:20px">Показать подходящие направления →</button>`)}
function oppEdit(id){const o=opportunitiesData.find(x=>x.id===id);if(!o)return;const d=oppDrafts[id]||{};openModal('Отклик: '+o.title,`<form id="opp-form" data-id="${id}"><label class="field">Почему вам интересно это направление? *<textarea name="message" required minlength="20" maxlength="2000" placeholder="Расскажите об опыте и о том, чем хотите помочь">${esc(d.message||'')}</textarea></label><label class="field" style="margin-top:15px">Когда удобно участвовать? *<select name="availability" required><option value="">Выберите</option>${['По будням','По выходным','Гибкий график','Разовые задачи'].map(x=>`<option ${d.availability===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field" style="margin-top:15px">Ссылка на портфолио (необязательно)<input name="portfolio" type="url" value="${esc(d.portfolio||'')}" placeholder="https://"></label><p class="muted-note">Пока сохраняем черновик на устройстве. Следующим шагом можно перенести отклик в анкету АКК.</p><button class="primary" style="margin-top:15px">Сохранить и продолжить →</button></form>`);$('#opp-form').onsubmit=e=>{e.preventDefault();oppDrafts[id]={...Object.fromEntries(new FormData(e.target)),updatedAt:new Date().toISOString()};storage.set('oppDrafts',oppDrafts);oppReady(id)}}
function oppReady(id){const o=opportunitiesData.find(x=>x.id===id),d=oppDrafts[id];$('#modal-label').textContent='Отклик подготовлен';$('#modal-content').innerHTML=`<div class="ready-state">${icon('check')}<h3>Хорошее начало.</h3><p>Черновик сохранён на устройстве. Он ещё не отправлен организатору.</p></div><div class="response-preview"><b>${o.title}</b><p>${esc(d.message)}</p><small>${esc(d.availability)}</small></div><button class="primary" data-opp-transfer="${id}" style="width:100%;margin-top:20px">Перенести в анкету АКК →</button><button class="secondary" data-opp-copy="${id}" style="width:100%;margin-top:10px">Скопировать отклик</button>`}
function filterOpps(){let list=opportunitiesData.filter(o=>(oppCategory==='Все'||o.category===oppCategory)&&(oppFormat==='Все'||o.format===oppFormat)&&(o.title+' '+o.category+' '+o.org+' '+o.skills.join(' ')).toLowerCase().includes(oppQuery.toLowerCase()));if(oppTab==='recommended')list.sort((a,b)=>oppScore(b)-oppScore(a));if($('#opp-list'))$('#opp-list').innerHTML=list.map(oppCard).join('')||'<p>Ничего не найдено. Измените фильтры.</p>';if($('#opp-count'))$('#opp-count').textContent='Найдено: '+list.length}
document.addEventListener('input',e=>{if(e.target.id==='opp-search'){oppQuery=e.target.value;filterOpps()}});
document.addEventListener('change',e=>{if(e.target.id==='opp-format'){oppFormat=e.target.value;filterOpps()}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='opp-quiz')oppQuiz();if(b.dataset.oppTab){oppTab=b.dataset.oppTab;route()}if(b.dataset.oppCategory){oppCategory=b.dataset.oppCategory;route()}if(b.dataset.oppEdit)oppEdit(b.dataset.oppEdit);if(b.dataset.oppRemove){delete oppDrafts[b.dataset.oppRemove];storage.set('oppDrafts',oppDrafts);route();toast('Черновик удалён')}if(b.id==='opp-quiz-save'){let selected=[...document.querySelectorAll('[name="opp-skill"]:checked')].map(x=>x.value);if(selected.length>5){toast('Выберите не больше пяти интересов');return}oppSkills=selected;storage.set('oppSkills',oppSkills);oppTab='recommended';closeModal();if(location.hash==='#opportunities')route();else location.hash='opportunities'}if(b.dataset.oppTransfer){const id=b.dataset.oppTransfer,o=opportunitiesData.find(x=>x.id===id),d=oppDrafts[id];draft.participation_interests=o.id==='business'?'Деловой клуб':o.id==='kpark'?'K-PARK и 90-летие':o.category==='Медиа'?'Медиа и коммуникации':o.category==='Культура'?'Творчество':o.category==='Сообщество'?'МДК':o.category;draft.about=[draft.about||'',`Отклик: ${o.title}\n${d.message}\nУдобное время: ${d.availability}${d.portfolio?'\nПортфолио: '+d.portfolio:''}`].filter(Boolean).join('\n\n');storage.set('draft',draft);closeModal();location.hash='profile';toast('Отклик перенесён. Проверьте анкету перед отправкой.')}if(b.dataset.oppCopy){const id=b.dataset.oppCopy,o=opportunitiesData.find(x=>x.id===id),d=oppDrafts[id];try{await navigator.clipboard.writeText(`${o.title}\n${d.message}\n${d.availability}\n${d.portfolio||''}`);toast('Отклик скопирован')}catch{toast('Выделите и скопируйте текст отклика')}}});

function newsPage(){const f=newsFilter==='Все'?news:news.filter(n=>n.category===newsFilter);return heading('МАТЕРИАЛЫ РЕДАКЦИИ','То, что нас объединяет.','Новости, культура и истории сообщества.')+`<div class="chips" role="group" aria-label="Темы публикаций">${['Все',...new Set(news.map(n=>n.category))].map(x=>`<button class="chip ${x===newsFilter?'active':''}" data-news-filter="${esc(x)}" aria-pressed="${x===newsFilter}">${esc(x)}</button>`).join('')}</div><div class="news-grid">${f.map(newsCard).join('')}</div><div class="form-actions">${ext('https://koreilbo.com/news/','Свежие публикации на сайте редакции','secondary')}<button class="secondary" id="refresh-news">Обновить ленту ↻</button></div><p class="muted-note" id="news-status">Материалы из открытых источников. При отсутствии связи сохраняется последняя доступная лента.</p>`}
function article(id){const n=news.find(x=>x.id===id);if(!n)return notFound();return `<div class="article">${back('news','Все материалы')}<div class="eyebrow">${esc(n.category)}</div><h1>${esc(n.title)}</h1><div class="meta">${esc(n.source)}<i></i>${formatDate(n.date)}<i></i>2026</div><div class="news-art type${n.art||0}"><span class="art-category">${esc(n.category)}</span></div>${n.body?n.body.map(p=>`<p>${esc(p)}</p>`).join(''):'<p>Материал опубликован редакцией «Корё ильбо». Полный текст доступен на сайте издания.</p>'}<div class="article-actions">${ext(n.url,'Читать в первоисточнике','primary')}${bookmark('news:'+n.id)}<button class="secondary" data-share="article/${esc(n.id)}">Поделиться</button></div><div class="source-label">Источник: ${esc(n.source)}. Иллюстрация в приложении — оформление рубрики.</div></div>`}
function field(label,name,type='text',required=false){return `<label class="field">${label}${required?' *':''}<input name="${name}" type="${type}" ${required?'required':''} value="${esc(draft[name]||'')}" ${name==='first_name'?'placeholder="Андрей" autocomplete="given-name"':name==='last_name'?'placeholder="Ли" autocomplete="family-name"':type==='tel'?'autocomplete="tel"':type==='email'?'autocomplete="email"':''} maxlength="${name==='first_name'||name==='last_name'?'100':'250'}"></label>`}
function profile(){let full=[draft.first_name,draft.last_name].filter(Boolean).join(' ');return `<button class="back sticky-back" id="profile-back">${icon('back')}Назад</button>`+heading('ЛИЧНОЕ ПРОСТРАНСТВО','Мой АКК','Ваши интересы, избранное и участие в жизни сообщества.')+`<div class="profile-layout"><div><div class="profile-header"><div class="profile-avatar">${esc((draft.first_name||'Я').slice(0,1).toUpperCase())}</div><div><h2>${esc(full||'Давайте познакомимся')}</h2><p>${session?'Вход выполнен':'Анкета участника'} · ${esc(region)}</p></div></div><div class="info-card"><h3>Несколько слов о себе</h3><p>Заполните анкету для передачи в Ассоциацию. Заполнение не означает автоматического подтверждения членства.</p><form id="profile-form"><div class="form-grid">${field('Имя','first_name','text',true)}${field('Фамилия','last_name','text',true)}${field('Отчество','middle_name')}${field('Дата рождения','birth_date','date',true)}${field('Электронная почта','email','email',true)}${field('Телефон','phone','tel',true)}<label class="field">Город *<select name="city" required><option value="">Выберите город</option>${regions.slice(1).map(x=>`<option ${draft.city===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Образование<select name="education_level"><option value="">Выберите</option>${['Среднее','Среднее специальное','Высшее','Послевузовское'].map(x=>`<option ${draft.education_level===x?'selected':''}>${x}</option>`).join('')}</select></label>${field('Учебное заведение','institution')}${field('Место работы','company')}${field('Должность','position')}<label class="field">Интересующее направление<select name="participation_interests"><option value="">Выберите направление</option>${['МДК','Волонтёрство','K-PARK и 90-летие','Образование','Медиа и коммуникации','Творчество','Деловой клуб'].map(x=>`<option ${draft.participation_interests===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field full">О себе<textarea name="about" maxlength="3000" placeholder="Ваш опыт, интересы и идеи">${esc(draft.about||'')}</textarea></label></div><label class="check"><input type="checkbox" name="consent" required><span>Согласен(на) на обработку указанных данных Ассоциацией для рассмотрения анкеты и обратной связи.</span></label><p><a class="text-link" href="#privacy">Об обработке данных</a></p><div class="form-actions"><button class="primary" type="submit">Отправить анкету ${icon('arrow')}</button><button class="secondary" type="button" id="save-draft">Сохранить черновик</button></div><div id="form-status" class="status-msg" role="status"></div><p class="muted-note">Черновик сохраняется только на этом устройстве. Успешная отправка подтверждается ответом сервера.</p></form></div></div><aside><div class="demo-member"><div class="eyebrow">ПРИМЕР ПРОФИЛЯ</div><div class="demo-avatar">ЛА</div><h3 data-no-translate>Ли Андрей</h3><p>Демонстрационный профиль</p></div><div class="rail-card"><h3>Уже с нами?</h3><p>Войдите по электронной почте, чтобы перейти к действующему личному кабинету.</p><button class="secondary" id="login-button">Войти в аккаунт →</button></div><div class="rail-card"><h3>Ваше избранное <span style="color:var(--purple)">${saved.size}</span></h3><p>Сохраняйте материалы и события, чтобы вернуться к ним позже.</p><a class="text-link" href="#saved">Открыть избранное →</a></div><div class="rail-card"><h3>Настройки</h3><button class="rail-row" id="theme-button" style="width:100%;text-align:left">${icon('sun')}Тёмная тема<span>${document.documentElement.classList.contains('dark')?'Вкл.':'Выкл.'}</span></button><button class="rail-row" id="install-profile" style="width:100%;text-align:left">${icon('download')}Установить приложение<span>→</span></button><a class="rail-row" href="./previous/index.html#profile">${icon('qr')}Карта и личный кабинет<span>↗</span></a></div></aside></div>`}
function savedPage(){const rows=[...saved].map(k=>{const [kind,id]=k.split(':');const x=kind==='news'?news.find(n=>n.id===id):kind==='opportunity'?opportunitiesData.find(n=>n.id===id):events.find(e=>e.id===id);return x?`<a href="#${kind==='news'?'article':kind==='opportunity'?'opportunity':'event'}/${esc(id)}">${esc(x.title)}<span>→</span></a>`:''}).join('');return back('profile','Профиль')+heading('МОИ СОХРАНЕНИЯ','Всё важное — под рукой.','Избранное сохраняется на этом устройстве.')+(rows?`<div class="saved-list">${rows}</div>`:empty('Пока ничего не сохранено','Нажмите значок закладки в карточке события или публикации.','Посмотреть материалы','news'))}
function contacts(){return back('community','Сообщество')+heading('ОСТАЁМСЯ НА СВЯЗИ','Контакты АКК','Официальные каналы Ассоциации и региональных филиалов.')+`<div class="info-card" style="padding:0">${[['mail','Электронная почта','oyulakk@gmail.com','mailto:oyulakk@gmail.com'],['globe','Официальный сайт','koreans.kz','https://koreans.kz/'],['pin','Региональные филиалы','Найдите контакты своего города','#branches'],['people','Instagram','@koreans_in_kazakhstan','https://www.instagram.com/koreans_in_kazakhstan/']].map(([i,t,p,u])=>`<a class="contact-row" href="${u}" ${u.startsWith('https')?'target="_blank" rel="noopener noreferrer"':''}>${icon(i)}<div><strong>${t}</strong><small>${p}</small></div><span>↗</span></a>`).join('')}</div><p class="muted-note">Контакты взяты из предоставленной версии приложения. Актуальную информацию проверяйте на официальном сайте.</p>`}
function about(){return heading('ОБ АССОЦИАЦИИ','Корни общие.<br>Будущее — наше.','Ассоциация казахстанских корейцев')+`<section class="association-intro"><img src="./assets/association/chai-urii.webp" alt="Цхай Юрий Андреевич"><div><div class="eyebrow">АССОЦИАЦИЯ КАЗАХСТАНСКИХ КОРЕЙЦЕВ</div><h2>Сохраняем наследие.<br>Объединяем поколения.</h2><p data-no-translate>Цхай Юрий Андреевич</p><small>Председатель Ассоциации казахстанских корейцев</small></div></section><div class="article"><p>Ассоциация объединяет корейское сообщество Казахстана, сохраняет культурное наследие и развивает общественные, молодёжные и деловые инициативы.</p><p>AKK Digital помогает находить своё региональное сообщество, узнавать о событиях, читать материалы «Корё ильбо» и выбирать возможности для участия.</p><div class="form-actions"><a class="primary" href="#community">Направления работы →</a><a class="secondary" href="#structure">Структура АКК →</a></div></div>`}
function anniversary(){return back('home','Главная')+heading('ПАМЯТЬ ПОКОЛЕНИЙ','90 лет. Одна история.','Программа 90-летия корейцев Казахстана · 2026–2027')+`<div class="feature-banner"><div class="eyebrow">СОХРАНЯЕМ · ОБЪЕДИНЯЕМ · СОЗДАЁМ</div><h2>Благодарность в памяти.<br>Будущее в наших руках.</h2><p>Культурные, исторические и общественные инициативы по всему Казахстану.</p><div class="actions"><a class="primary" href="#opportunities">Стать частью программы →</a></div></div>${section('Ключевые события')}<div class="event-list">${events.map(eventCard).join('')}</div>`}
function benefits(){return back('business','Деловой клуб')+heading('ПРИВИЛЕГИИ УЧАСТНИКОВ','Возможности сообщества','Партнёрская программа АКК')+empty('Программа формируется','Компании, размер скидок, сроки и условия будут опубликованы после согласования. Подтверждённые привилегии доступны участникам с действующим статусом.','Заполнить анкету','profile')}
function privacy(){return back('profile','Анкета')+heading('ВАШИ ДАННЫЕ','Об обработке анкеты','Прозрачно и по делу')+`<div class="article"><h3>Что сохраняется на устройстве</h3><p>Черновик анкеты сохраняется в браузере после нажатия «Сохранить черновик» или «Назад». Избранное, выбранный регион и тема также хранятся на этом устройстве.</p><h3>Что передаётся при отправке</h3><p>При нажатии «Отправить анкету» указанные сведения передаются в действующую систему АКК для рассмотрения и обратной связи. Отправка выполняется только после вашего согласия.</p><h3>Как удалить черновик</h3><p>Используйте кнопку ниже или очистите данные приложения в настройках браузера. Для вопросов об отправленной анкете обратитесь в Ассоциацию.</p><div class="form-actions"><button class="secondary" id="clear-draft">Удалить черновик с устройства</button><a class="secondary" href="#contacts">Связаться с АКК</a></div></div>`}
function notFound(){return heading('AKK DIGITAL','Страница не найдена','Возможно, ссылка изменилась.')+'<a class="primary" href="#home">На главную →</a>'}
const aliases={connect:'community',akk:'about',delovoy:'business',teatr:'theatre','teatr-afisha':'theatre','branches-list':'branches','gazeta-all-news':'news','kpark-donate':'kpark-support','member-card':'profile','mdk-opportunities':'opportunities',settings:'profile','akk-contacts':'contacts','mdk-structure':'structure'};
function route(){let [page,arg]=location.hash.slice(1).split('/');page=aliases[page]||page||'home';if(!location.hash)history.replaceState(null,'','#home');const f={home,community,events:eventsPage,kpark,profile,branches,structure,opportunities,news:newsPage,saved:savedPage,contacts,about,anniversary,benefits,privacy,'kpark-about':kparkAbout,'kpark-support':support};try{if(f[page])main.innerHTML=f[page]();else if(departments.some(d=>d.id===page))main.innerHTML=department(page);else if(page==='opportunity')main.innerHTML=opportunityDetail(arg);else if(page==='article')main.innerHTML=article(decodeURIComponent(arg||''));else if(page==='event')main.innerHTML=eventDetail(arg);else if(page==='branch')main.innerHTML=branchDetail(decodeURIComponent(arg||''));else main.innerHTML=notFound()}catch{main.innerHTML=notFound()}const group=page.startsWith('kpark')?'kpark':['article','gazeta','news'].includes(page)?'community':['event','anniversary'].includes(page)?'events':['saved','privacy'].includes(page)?'profile':departments.some(d=>d.id===page)||['branches','branch','structure','opportunities','about','contacts','benefits'].includes(page)?'community':page;$('#desktop-nav').innerHTML=nav.map(([id,t,i])=>`<a href="#${id}" class="nav-item ${id===group?'active':''}" ${id===group?'aria-current="page"':''}>${icon(i)}${t}</a>`).join('');$('#mobile-nav').innerHTML=nav.map(([id,t,i])=>`<a href="#${id}" class="${id===group?'active':''}" ${id===group?'aria-current="page"':''}>${icon(i)}${t}</a>`).join('');$('#breadcrumb').textContent='AKK Digital / '+(nav.find(x=>x[0]===group)?.[1]||'Сообщество');$('#region-button').innerHTML=icon('pin')+esc(region==='Весь Казахстан'?'Казахстан':region)+'⌄';document.title=(main.querySelector('h1')?.textContent||'AKK Digital')+' · AKK Digital';if($('#profile-form')){$('#profile-form').addEventListener('submit',submitProfile);$('#profile-form').addEventListener('input',()=>{draft=Object.fromEntries(new FormData($('#profile-form')));delete draft.consent})}$('#branch-search')?.addEventListener('input',e=>$('#branch-list').innerHTML=branchCards(e.target.value));window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true})}
function openModal(label,html){returnFocus=document.activeElement;$('#modal-label').textContent=label;$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();const f=$('input', $('#modal-content'));f?.focus()}
function closeModal(){$('#modal').close();returnFocus?.focus?.()}
function showRegions(){openModal('Ваш регион',`<p>Покажем события выбранного города. Выбор можно изменить в любой момент.</p><div class="modal-grid">${regions.map(x=>`<button data-region="${x}" class="${region===x?'selected':''}">${x}</button>`).join('')}</div>`)}
function showSearch(){openModal('Поиск в AKK Digital','<input id="global-search" class="search-input" type="search" placeholder="Раздел, город или публикация…" aria-label="Поиск по приложению"><div class="search-results" id="search-results"></div>');searchResults('');$('#global-search').addEventListener('input',e=>searchResults(e.target.value))}
function searchResults(q){let items=[...nav.map(([id,title])=>({title,route:id,type:'Раздел'})),...departments.map(d=>({title:d.name,route:d.id,type:d.label})),...regions.slice(1).map(c=>({title:c,route:'branch/'+encodeURIComponent(c),type:'Филиал АКК'})),...news.map(n=>({title:n.title,route:'article/'+n.id,type:'Корё ильбо'})),{title:'Волонтёрство и возможности',route:'opportunities',type:'Участие'},{title:'Структура Ассоциации',route:'structure',type:'АКК'}];let f=items.filter(x=>x.title.toLowerCase().includes(q.trim().toLowerCase())).slice(0,12);$('#search-results').innerHTML=f.map(x=>`<a class="search-result" data-close-search href="#${x.route}"><span>${esc(x.title)}<small>${x.type}</small></span>${icon('arrow')}</a>`).join('')||'<p>Ничего не найдено. Попробуйте другой запрос.</p>'}
async function request(path,options={}){if(!config.supabaseUrl||!config.publishableKey)throw Error('Сервис временно недоступен. Черновик можно сохранить и отправить позже.');const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),12000);try{const r=await fetch(config.supabaseUrl+path,{...options,signal:controller.signal,headers:{apikey:config.publishableKey,'Content-Type':'application/json',...(session?{Authorization:'Bearer '+session.access_token}:{}),...options.headers}});const data=await r.json().catch(()=>null);if(!r.ok)throw Error(data?.msg||data?.message||data?.error_description||'Сервис пока не принял запрос. Попробуйте позже.');return data}finally{clearTimeout(timer)}}
async function submitProfile(e){e.preventDefault();const f=e.target,fd=new FormData(f),b=$('button[type=submit]',f),status=$('#form-status');if(!f.reportValidity())return;const phone=String(fd.get('phone')).replace(/[^\d+]/g,'');if(phone.replace(/\D/g,'').length<10){status.className='status-msg error';status.textContent='Проверьте номер телефона: укажите код страны и номер.';return}const born=new Date(fd.get('birth_date'));if(born>new Date()){status.className='status-msg error';status.textContent='Дата рождения не может быть в будущем.';return}const data=Object.fromEntries(fd);delete data.consent;delete data.email;data.phone=phone;const email=String(fd.get('email')).trim();b.disabled=true;b.textContent='Отправляем…';status.textContent='';try{await request('/rest/v1/rpc/submit_guest_questionnaire',{method:'POST',body:JSON.stringify({p_request_id:storage.get('requestId',null)||getRequestId(),p_email:email,p_data:data})});status.className='status-msg';status.textContent='Анкета принята сервером. Ассоциация свяжется с вами при необходимости. Членство подтверждается отдельно.';storage.set('submittedAt',new Date().toISOString());storage.set('requestId',null);toast('Анкета отправлена')}catch(err){status.className='status-msg error';status.textContent=(err.name==='AbortError'?'Не удалось дождаться ответа сервера.':err.message)+' Анкета не подтверждена как отправленная. Сохраните черновик и повторите позже.'}finally{b.disabled=false;b.innerHTML='Отправить анкету '+icon('arrow')}}
function getRequestId(){const id=crypto.randomUUID();storage.set('requestId',id);return id}
function saveDraft(){const fd=new FormData($('#profile-form'));draft=Object.fromEntries(fd);delete draft.consent;storage.set('draft',draft);toast('Черновик сохранён на этом устройстве')}
function login(){openModal('Вход в личный кабинет',`<p>Получите письмо со ссылкой или кодом. Если подтверждение почты недоступно, анкету можно отправить без входа.</p><form id="login-form"><label class="field">Электронная почта<input type="email" name="email" required autocomplete="email" placeholder="you@example.com"></label><button class="primary" style="margin-top:18px">Отправить письмо</button><div class="status-msg" id="login-status" role="status"></div></form>`);$('#login-form').onsubmit=async e=>{e.preventDefault();const form=e.target,btn=$('button',form),email=new FormData(form).get('email');btn.disabled=true;try{await request('/auth/v1/otp?redirect_to='+encodeURIComponent(new URL('./previous/index.html',location.href).href),{method:'POST',body:JSON.stringify({email,create_user:true})});authEmail=email;$('#login-status').textContent='Запрос принят. Проверьте последнее письмо, в том числе папку «Спам». Если в письме код, введите его ниже.';if(!$('#otp-form'))$('#modal-content').insertAdjacentHTML('beforeend','<form id="otp-form" style="margin-top:20px"><label class="field">Код из письма<input name="token" inputmode="numeric" autocomplete="one-time-code" required minlength="6" maxlength="10"></label><button class="secondary" style="margin-top:12px">Подтвердить код</button><p id="otp-status" class="status-msg"></p></form>');$('#otp-form').onsubmit=verifyOtp}catch(err){$('#login-status').className='status-msg error';$('#login-status').textContent=err.name==='AbortError'?'Сервис не ответил. Попробуйте позже.':err.message}finally{btn.disabled=false}}}
async function verifyOtp(e){e.preventDefault();const btn=$('button',e.target);btn.disabled=true;try{session=await request('/auth/v1/verify',{method:'POST',body:JSON.stringify({email:authEmail,token:new FormData(e.target).get('token'),type:'email'})});const authKey='sb-'+new URL(config.supabaseUrl).hostname.split('.')[0]+'-auth-token';localStorage.setItem(authKey,JSON.stringify(session));$('#otp-status').textContent='Вход подтверждён. Перейдите в кабинет для доступа к карте участника и своим данным.';$('#otp-form').insertAdjacentHTML('beforeend','<a class="primary" href="./previous/index.html#profile">Открыть кабинет →</a>')}catch(err){$('#otp-status').textContent=err.message}finally{btn.disabled=false}}
async function refreshNews(show=false){try{const r=await fetch('./news.json',{cache:'no-store'});if(r.ok){const data=await r.json();if(Array.isArray(data.items)&&data.items.length){news=data.items;if(['home','news','gazeta'].includes(location.hash.slice(1)))route();if(show)toast('Лента обновлена')}}}catch{if(show)toast('Нет связи. Показана сохранённая лента.')}}
function calendarFile(id){const e=events.find(x=>x.id===id);if(!e)return;const next=new Date(e.date+'T12:00:00');next.setDate(next.getDate()+1);const end=next.toISOString().slice(0,10).replaceAll('-','');const text=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//AKK Digital//Community//RU','BEGIN:VEVENT','UID:'+e.id+'@akk-digital','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTSTART;VALUE=DATE:'+e.date.replaceAll('-',''),'DTEND;VALUE=DATE:'+end,'SUMMARY:'+e.title.replace(/[,;]/g,' '),'LOCATION:'+e.city,'DESCRIPTION:Плановое мероприятие. Время и площадка уточняются.','END:VEVENT','END:VCALENDAR'].join('\r\n');download(new Blob([text],{type:'text/calendar;charset=utf-8'}),e.id+'.ics')}
function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function install(){if(deferredInstall){await deferredInstall.prompt();deferredInstall=null;return}openModal('Приложение всегда рядом',`<div class="app-promo"><h3>На iPhone</h3><p>Откройте эту страницу в Safari, нажмите «Поделиться», затем «На экран Домой».</p><h3>На Android</h3><p>В меню Chrome выберите «Установить приложение» или «Добавить на главный экран».</p><p>Если страница открыта во встроенном браузере мессенджера, сначала откройте её в Safari или Chrome.</p></div>`)}
document.addEventListener('click',async e=>{const el=e.target.closest('button,a');if(!el)return;if(el.classList.contains('skip')){e.preventDefault();main.focus();return}if(el.dataset.closeSearch!==undefined)closeModal();if(el.dataset.save){const id=el.dataset.save;saved.has(id)?saved.delete(id):saved.add(id);storage.set('saved',[...saved]);el.classList.toggle('saved',saved.has(id));el.setAttribute('aria-pressed',String(saved.has(id)));el.setAttribute('aria-label',saved.has(id)?'Убрать из избранного':'Добавить в избранное');toast(saved.has(id)?'Сохранено в избранное':'Удалено из избранного')}if(el.dataset.region){region=el.dataset.region;storage.set('region',region);closeModal();route()}if(el.dataset.newsFilter){newsFilter=el.dataset.newsFilter;route()}if(el.dataset.eventFilter){eventFilter=el.dataset.eventFilter;route()}if(el.dataset.calendar)calendarFile(el.dataset.calendar);if(el.dataset.share){const url=location.href.split('#')[0]+'#'+el.dataset.share;try{if(navigator.share)await navigator.share({title:'AKK Digital',url});else{await navigator.clipboard.writeText(url);toast('Ссылка скопирована')}}catch(err){if(err.name!=='AbortError')openModal('Поделиться ссылкой',`<input class="search-input" readonly value="${esc(url)}" aria-label="Ссылка для копирования">`)}}if(el.id==='profile-back'){saveDraft();location.hash='home'}if(el.id==='save-draft')saveDraft();if(el.id==='login-button')login();if(el.id==='theme-button'){const dark=document.documentElement.classList.toggle('dark');storage.set('dark',dark);route()}if(el.id==='clear-draft'){draft={};storage.set('draft',{});toast('Черновик удалён с устройства')}if(el.id==='refresh-news')refreshNews(true);if(['install-button','install-profile'].includes(el.id))install()});
$('#search-button').innerHTML=icon('search');$('#search-button').onclick=showSearch;$('#region-button').onclick=showRegions;$('#account-button').onclick=()=>location.hash='profile';$('#close-modal').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});window.addEventListener('hashchange',()=>{if($('#modal').open)closeModal();route()});window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e});

const zoneImages={1:'03-vhod',2:'04-vizit-centr',3:'07-bashnya-den',4:'10-kulturnyy-centr',5:'11-holl',6:'15-koryo-saram',7:'16-koreyskiy-sad',8:'16b-sad-sverhu',9:'17-amfiteatr',10:'18-gastrozona',13:'02-trassa'};
const parkRenderTitles=['Панорама парка','Трасса и подъезд','Входная площадь','Визит-центр','Фудкорт','Основание обзорной башни','Башня днём','Башня вечером','Вечерняя прогулка','Культурно-деловой центр','Холл','Библиотека','Конференц-зал','Интерьер','Пространство Корё сарам','Корейский сад','Корейский сад с высоты','Амфитеатр','Гастрозона'];
const parkRenderFiles=['01-hero','02-trassa','03-vhod','04-vizit-centr','05-fudkort','06-bashnya-osnovanie','07-bashnya-den','08-bashnya-noch','09-dorozhka','10-kulturnyy-centr','11-holl','12-biblioteka','13-konferenc-zal','14-interier','15-koryo-saram','16-koreyskiy-sad','16b-sad-sverhu','17-amfiteatr','18-gastrozona'];
function parkGallery(){return `<section class="park-gallery-section"><div class="section-heading"><div><div class="eyebrow">АРХИТЕКТУРА И ПРИРОДА</div><h2>Будущий K-PARK в деталях</h2></div><span>19</span></div><p class="muted-note">Архитектурные рендеры проекта. Визуализации будущих пространств.</p><div class="park-gallery">${parkRenderFiles.map((file,i)=>`<button class="render-card" data-render="${i}" aria-label="${esc(parkRenderTitles[i])}"><img src="./assets/kpark/${file}.webp" alt="${esc(parkRenderTitles[i])} — рендер проекта" loading="lazy"><span><small>${String(i+1).padStart(2,'0')}</small><strong>${parkRenderTitles[i]}</strong>${icon('arrow')}</span></button>`).join('')}</div></section>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-render]');if(!b)return;const i=Number(b.dataset.render);if(!Number.isInteger(i)||!parkRenderFiles[i])return;openModal('K-PARK · рендер проекта',`<img class="render-full" src="./assets/kpark/${parkRenderFiles[i]}.webp" alt="${esc(parkRenderTitles[i])}"><h3>${parkRenderTitles[i]}</h3><div class="render-nav"><button class="secondary" data-render="${(i+18)%19}">← Назад</button><span>${i+1} / 19</span><button class="secondary" data-render="${(i+1)%19}">Далее →</button></div>`)});
document.addEventListener('error',e=>{const img=e.target;if(img.tagName==='IMG'&&!img.dataset.fallback){img.dataset.fallback='true';img.src='./assets/fallback.svg';img.alt='Иллюстрация AKK Digital'}},true);route();setInterval(()=>{if(document.visibilityState==='visible')refreshNews()},300000);fetch('./config.json').then(r=>r.ok?r.json():{}).then(c=>config=c).catch(()=>{});refreshNews();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});

document.addEventListener('click',e=>{const a=e.target.closest('[data-council]');if(a){e.preventDefault();document.getElementById('council-'+a.dataset.council)?.scrollIntoView({behavior:'smooth',block:'start'})}});
